"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { ArrowLeft, ChevronLeft, ChevronRight, Sparkles, X } from "lucide-react";
import Card from "../components/ui/Card";
import EvidenceImage from "../components/progress/EvidenceImage";
import IconBadge from "../components/ui/IconBadge";
import ActionButton from "../components/ui/ActionButton";

export function createOrdinaryPhotoComparisonEntries(narrative={}) {
  return (narrative.cardContent?.progress?.comparisons??[])
    .filter((entry)=>entry?.id&&entry?.poseId&&entry?.label&&entry?.imageHref&&entry?.previousImageHref&&entry?.previousDate)
    .map((entry)=>({
      id:entry.id,
      poseId:entry.poseId,
      poseLabel:entry.label,
      firstDate:entry.previousDate,
      currentDate:narrative.eventDate,
      observations:[entry.headline,...(entry.supportingObservations??[]),...(entry.findings??[])].filter(Boolean),
      viewerGalleryItems:[
        {id:`${entry.id}-previous`,imageHref:entry.previousImageHref,date:entry.previousDate,roleLabel:"Previous",poseLabel:entry.label},
        {id:`${entry.id}-current`,imageHref:entry.imageHref,date:narrative.eventDate,roleLabel:"Current",poseLabel:entry.label},
      ],
    }));
}

export default function PhotoEventBriefingScreen({ artifactId = null, completion = null, completeAction = null, narrative }) {
  const cards=narrative.cardContent;
  const completionExperience=narrative.completionExperience;
  const ordinaryComparisons=createOrdinaryPhotoComparisonEntries(narrative);
  const completed=completion?.evidence?.finalPhotoSessionId===narrative.photoSessionId;
  const [viewer,setViewer]=useState(null);
  const viewerOpen=Boolean(viewer);
  const scrollPosition=useRef(0);
  function openViewer(items,index=0){scrollPosition.current=window.scrollY;setViewer({items,index});}
  function closeViewer(){setViewer(null);}
  useEffect(()=>{if(!viewerOpen)return undefined;const body=document.body;const previous={position:body.style.position,top:body.style.top,width:body.style.width,overflow:body.style.overflow};body.style.position="fixed";body.style.top=`-${scrollPosition.current}px`;body.style.width="100%";body.style.overflow="hidden";return()=>{body.style.position=previous.position;body.style.top=previous.top;body.style.width=previous.width;body.style.overflow=previous.overflow;window.scrollTo({top:scrollPosition.current,behavior:"instant"});};},[viewerOpen]);
  return <main className="app-surface mx-auto min-h-screen max-w-[393px] overflow-x-hidden"><div className="px-4 pb-32 pt-7 sm:pt-10">
    <Link className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-slate-500" href="/progress/photos"><ArrowLeft size={18}/>Progress Photos</Link>
    <section className="mb-5 space-y-3" data-testid="photo-event-hero"><div className="flex items-center gap-3"><IconBadge color="warning" icon={Sparkles} size="md"/><p className="text-sm font-semibold uppercase tracking-[0.12em] text-indigo-600">Photo Event</p></div><h1 className="text-[30px] font-extrabold leading-[1.12] text-slate-950">{cards.hero.title}</h1><p className="text-sm font-semibold leading-6 text-slate-500">{cards.hero.body}</p></section>
    <div className="space-y-3">
      <Card data-testid="photo-event-snapshot"><Eyebrow>Snapshot</Eyebrow><h2 className="mt-1 text-lg font-extrabold">{cards.snapshot.title}</h2><div className="mt-3 grid grid-cols-3 gap-2 text-center"><SnapshotFact label="Date" value={formatDate(narrative.eventDate)}/><SnapshotFact label="Set" value={narrative.completion}/><SnapshotFact label="Weight" value={narrative.supportingEvidence.weight}/></div><p className="mt-3 text-xs font-semibold leading-5 text-slate-500">{cards.snapshot.poses.join(" · ")}</p><p className="mt-1 text-xs font-semibold leading-5 text-slate-500">{cards.snapshot.conditions}</p><div className="mt-3 grid grid-cols-3 gap-2">{narrative.activeViews.map((view,index)=><button aria-label={`Open ${view.label} viewer`} className="overflow-hidden rounded-xl" key={view.id} onClick={()=>openViewer(narrative.activeViews.map((item)=>({id:item.id,imageHref:item.imageHref,date:narrative.eventDate,roleLabel:"Final",poseLabel:item.label})),index)} type="button"><EvidenceImage alt={view.label} className="aspect-[3/4] w-full object-cover" src={view.imageHref}/></button>)}</div></Card>
      {completionExperience?<><ComparisonSection entries={completionExperience.recentComparisons} intro="The final week brought smaller refinements through the waist, lower midsection, and back conditioning." onOpen={openViewer} scope="recent" title="Since last check-in"/><ComparisonSection entries={completionExperience.journeyComparisons} intro="The full journey shows the larger transformation from the beginning of the cut to the final photo set." onOpen={openViewer} scope="journey" title="From first upload to now"/><Card data-testid="photo-event-new-baselines"><Eyebrow>Progress</Eyebrow><h2 className="mt-1 text-lg font-extrabold">New baseline views</h2><div className="mt-3 space-y-3">{completionExperience.newBaselineViews.map((view)=><NewBaselineCard key={view.id} onOpen={()=>openViewer([{id:view.id,imageHref:view.imageHref,date:narrative.eventDate,roleLabel:"First recorded",poseLabel:view.label}])} view={view}/>)}</div></Card></>:ordinaryComparisons.length?<ComparisonSection entries={ordinaryComparisons} intro={cards.progress.body} onOpen={openViewer} scope="ordinary" title={cards.progress.title}/>:<Card data-testid="photo-event-progress"><Eyebrow>Progress</Eyebrow><h2 className="mt-1 text-lg font-extrabold">{cards.progress.title}</h2><p className="mt-2 text-sm font-semibold leading-6 text-slate-600">{cards.progress.body}</p></Card>}
      <Card data-testid="photo-event-interpretation"><Eyebrow>Interpretation</Eyebrow><h2 className="mt-1 text-lg font-extrabold">{cards.interpretation.title}</h2><div className="mt-2 space-y-2">{cards.interpretation.paragraphs.map((value)=><p className="text-sm font-semibold leading-6 text-slate-600" key={value}>{value}</p>)}</div></Card>
      <Card data-testid="photo-event-coach"><Eyebrow>Coach’s Insight</Eyebrow><p className="mt-2 text-sm font-semibold leading-6 text-slate-700">{cards.coachInsight.body}</p>{!completionExperience&&narrative.nextMilestone?.label&&<p className="mt-3 rounded-xl bg-[var(--surface-muted)] p-3 text-xs font-extrabold text-slate-600">Next: {narrative.nextMilestone.label}</p>}</Card>
      {completionExperience&&<CompletionDecision artifactId={artifactId} completeAction={completeAction} completed={completed} completion={completion} experience={completionExperience} narrative={narrative}/>}
    </div>
  </div>{viewer&&<PhotoViewer activeIndex={viewer.index} items={viewer.items} onClose={closeViewer} onIndexChange={(index)=>setViewer((current)=>({...current,index}))}/>}</main>;
}
function ComparisonSection({entries,intro,onOpen,scope,title}){return <Card data-testid={`photo-event-${scope}-comparisons`}><Eyebrow>Progress</Eyebrow><h2 className="mt-1 text-lg font-extrabold">{title}</h2><p className="mt-2 text-sm font-semibold leading-6 text-slate-600">{intro}</p><div className="mt-4 space-y-5">{entries.map((entry)=><button className="block w-full text-left" data-testid={`${scope}-comparison-${entry.poseId}`} key={entry.id} onClick={()=>onOpen(entry.viewerGalleryItems)} type="button"><div className="flex items-end justify-between gap-3"><div><h3 className="text-sm font-extrabold text-slate-900">{entry.poseLabel}</h3><p className="text-xs font-bold text-slate-400">{formatDate(entry.firstDate)} → {formatDate(entry.currentDate)}</p></div><span className="text-xs font-extrabold text-[var(--primary)]">Tap to expand</span></div><p className="mt-1 text-xs font-semibold leading-5 text-slate-600">{entry.observations[0]}</p><div className="mt-2 grid grid-cols-2 gap-2">{entry.viewerGalleryItems.map((item)=><ComparisonImage item={item} key={item.id}/>)}</div></button>)}</div></Card>}
function ComparisonImage({item}){return <figure className="min-w-0"><EvidenceImage alt={`${item.roleLabel} ${item.poseLabel}`} className="aspect-[3/4] w-full rounded-xl object-cover" src={item.imageHref}/><figcaption className="mt-1 text-center"><span className="block text-xs font-extrabold text-slate-700">{formatDate(item.date)}</span><span className="text-[9px] font-black uppercase tracking-[.08em] text-slate-400">{item.roleLabel}</span></figcaption></figure>}
function CompletionDecision({artifactId,completeAction,completed,completion,experience,narrative}){if(completed)return <><Card className="border-emerald-200/80 bg-emerald-50/60" data-testid="photo-event-completed"><Eyebrow>Goal achieved</Eyebrow><h2 className="mt-1 text-xl font-extrabold">Visible Abs at Rest is complete.</h2><p className="mt-2 text-sm font-semibold leading-6 text-slate-700">You finished the cut at 7.7% body fat while preserving lean mass.</p><p className="mt-3 text-xs font-bold text-emerald-700">Completed {formatDate(completion.completedAt)}</p></Card><NextGoalPreview preview={experience.nextGoalPreview}/></>;if(experience.state==="confirmed"&&experience.userDecision)return <section className="rounded-2xl border-t-2 border-indigo-400 bg-slate-950 p-5 text-white shadow-sm" data-testid="photo-event-user-decision"><p className="text-[10px] font-extrabold uppercase tracking-[.12em] text-indigo-300">Your decision</p><h2 className="mt-2 text-lg font-extrabold leading-6">{experience.userDecision.question}</h2><p className="mt-2 text-xs font-semibold leading-5 text-slate-300">Only your explicit choice closes the goal.</p><form action={completeAction} className="mt-4"><input name="photoSessionId" type="hidden" value={narrative.photoSessionId}/><input name="photoEventBriefingId" type="hidden" value={artifactId}/><ActionButton type="submit">{experience.userDecision.completeLabel}</ActionButton></form><Link className="mt-3 flex min-h-12 w-full items-center justify-center rounded-[14px] bg-slate-800 px-4 text-sm font-extrabold text-slate-100 transition hover:bg-slate-700" href="/goals/visible-abs">{experience.userDecision.keepOpenLabel}</Link></section>;const retryHref="/evidence/photos?goalId=goal_visible_abs_at_rest&confirmationPurpose=visible_abs_completion&numericalThresholdComplete=true&visualCriterionComplete=uncertain&criterion=lower_abs_visible_at_rest&requiredPose=front-relaxed&userConfirmationRequired=true&requestedEvidence=relaxed_front_photo&sourceContext=photo_event_retry";return <Card data-testid="photo-event-retry"><Eyebrow>{experience.state==="not_confirmed"?"Goal remains open":"Clearer photo needed"}</Eyebrow><p className="mt-2 text-sm font-semibold leading-6 text-slate-700">{experience.state==="not_confirmed"?"You can keep the goal open without changing the DEXA conclusion.":"A replacement qualified front relaxed photo can resolve the visual decision."}</p><Link className="mt-4 flex min-h-12 w-full items-center justify-center rounded-[14px] bg-[var(--primary)] px-4 text-sm font-extrabold text-white" href={retryHref}>Upload Again</Link></Card>}
function NextGoalPreview({preview}){return <Card data-testid="next-goal-preview"><Eyebrow>What would you like to do next?</Eyebrow><h2 className="mt-1 text-lg font-extrabold">{preview.title}</h2><p className="mt-2 text-sm font-semibold leading-6 text-slate-600">The cut is complete, you are currently 7.7%, and lean mass was preserved. A controlled lean-mass phase with body fat as the guardrail is the recommended direction.</p><button className="mt-4 min-h-12 w-full cursor-not-allowed rounded-[14px] bg-slate-200 px-4 text-sm font-extrabold text-slate-500" disabled type="button">{preview.actionLabel} · Coming next</button></Card>}
function NewBaselineCard({onOpen,view}){return <button className="grid w-full grid-cols-[96px_1fr] gap-3 rounded-xl bg-[var(--surface-muted)] p-3 text-left" data-testid="new-pose-baseline" onClick={onOpen} type="button"><EvidenceImage alt={view.label} className="aspect-[3/4] w-24 rounded-xl object-cover" src={view.imageHref}/><div><span className="inline-flex rounded-full bg-[var(--surface-accent)] px-2 py-1 text-[10px] font-extrabold text-[var(--primary)]">First recorded view</span><h4 className="mt-2 text-sm font-extrabold text-slate-900">{view.label}</h4><p className="mt-1 text-xs font-semibold leading-5 text-slate-600">{view.baselineNarrative}</p></div></button>}
function SnapshotFact({label,value}){return <div className="rounded-xl bg-[var(--surface-muted)] p-2"><p className="text-[9px] font-extrabold uppercase tracking-[0.08em] text-slate-400">{label}</p><p className="mt-1 text-xs font-extrabold text-slate-700">{value}</p></div>}
function PhotoViewer({activeIndex,items,onClose,onIndexChange}){const gesture=useRef(null);const [dragOffset,setDragOffset]=useState(0);const [dragging,setDragging]=useState(false);const [zooming,setZooming]=useState(false);const view=items[activeIndex];useEffect(()=>{function key(event){if(event.key==="Escape")onClose();if(event.key==="ArrowLeft")onIndexChange((activeIndex-1+items.length)%items.length);if(event.key==="ArrowRight")onIndexChange((activeIndex+1)%items.length);}window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key);},[activeIndex,onClose,onIndexChange,items.length]);useEffect(()=>{for(const index of [(activeIndex-1+items.length)%items.length,(activeIndex+1)%items.length]){const preload=new Image();preload.src=items[index].imageHref;}},[activeIndex,items]);function start(event){if(event.touches.length>1){setZooming(true);gesture.current=null;return;}setZooming(false);gesture.current={x:event.touches[0].clientX,time:performance.now()};setDragging(true);}function move(event){if(zooming||event.touches.length!==1||!gesture.current)return;const offset=event.touches[0].clientX-gesture.current.x;setDragOffset(offset);if(Math.abs(offset)>8)event.preventDefault();}function end(event){if(zooming){setZooming(false);setDragging(false);setDragOffset(0);return;}if(!gesture.current||event.changedTouches.length!==1)return;const delta=event.changedTouches[0].clientX-gesture.current.x;const elapsed=Math.max(performance.now()-gesture.current.time,1);const velocity=delta/elapsed;if(Math.abs(delta)>window.innerWidth*.22||Math.abs(velocity)>.45)onIndexChange((activeIndex+(delta<0?1:-1)+items.length)%items.length);gesture.current=null;setDragging(false);setDragOffset(0);}const transform=`translateX(calc(${-(activeIndex*100)/items.length}% + ${dragOffset}px))`;return <div aria-label="Photo comparison viewer" className="fixed inset-0 z-[100] flex flex-col overscroll-none bg-slate-950 text-white" data-testid="photo-event-viewer" role="dialog"><div className="flex items-center justify-between px-4 py-3"><button aria-label="Close viewer" className="rounded-full bg-white/10 p-2" onClick={onClose} type="button"><X size={20}/></button><div className="text-center"><p className="text-sm font-extrabold">{view.poseLabel}</p><p className="text-[10px] font-bold text-slate-400">{activeIndex+1} of {items.length}</p></div><span className="w-9"/></div><div className="min-h-0 flex-1 overflow-hidden overscroll-contain [touch-action:pinch-zoom]" onTouchCancel={end} onTouchEnd={end} onTouchMove={move} onTouchStart={start}><div className={`flex h-full ${dragging?"":"transition-transform duration-300 ease-out"}`} data-testid="photo-viewer-track" style={{transform,width:`${items.length*100}%`}}>{items.map((item)=><div className="flex h-full shrink-0 overflow-auto px-1 pb-3" key={item.id} style={{width:`${100/items.length}%`}}><ViewerImage date={item.date} label={item.roleLabel} src={item.imageHref}/></div>)}</div></div><div className="flex items-center justify-between px-5 py-4"><button aria-label="Previous photo" className="rounded-full bg-white/10 p-3" onClick={()=>onIndexChange((activeIndex-1+items.length)%items.length)} type="button"><ChevronLeft/></button><p className="text-xs font-bold text-slate-400">Swipe between photos · Pinch to zoom</p><button aria-label="Next photo" className="rounded-full bg-white/10 p-3" onClick={()=>onIndexChange((activeIndex+1)%items.length)} type="button"><ChevronRight/></button></div></div>}
function ViewerImage({date,label,src}){return <figure className="flex min-w-0 flex-col justify-center">{src?<EvidenceImage alt={`${label} photo`} className="max-h-[78vh] w-full object-contain" src={src}/>:<div className="flex aspect-[3/4] items-center justify-center bg-white/5 text-xs text-slate-500">No prior photo</div>}<figcaption className="p-2 text-center"><span className="block text-sm font-extrabold">{formatDate(date)}</span><span className="text-[9px] font-bold uppercase tracking-[0.08em] text-slate-400">{label}</span></figcaption></figure>}
function Eyebrow({children}){return <p className="text-[10px] font-extrabold uppercase tracking-[0.1em] text-[var(--primary)]">{children}</p>}
function formatDate(value){if(!value)return "—";const [y,m,d]=String(value).slice(0,10).split("-").map(Number);return new Date(y,m-1,d).toLocaleDateString("en-US",{month:"short",day:"numeric"});}
